import json
from datetime import date
from typing import Literal
from pydantic import BaseModel, Field, ValidationError

class SalesSummaryArgs(BaseModel):
    start_date: date
    end_date: date
    group_by: Literal["day", "sku", "marketplace"] = "day"
    limit: int = Field(default=20, ge=1, le=100)

TOOLS = [{
    "type": "function",
    "function": {
        "name": "get_sales_summary",
        "description": "Revenue and units for the current organisation between two dates. Use for any sales/revenue question.",
        "parameters": SalesSummaryArgs.model_json_schema(),
    },
}]

def get_sales_summary(args: SalesSummaryArgs, *, org_id: int) -> list[dict]:
    sql = '''SELECT date_trunc('day', o.created_at)::date AS day, SUM(oi.quantity*oi.unit_price) AS revenue
             FROM orders o JOIN order_items oi ON oi.order_id = o.id
             WHERE o.org_id = %s AND o.created_at >= %s AND o.created_at < %s + 1
             GROUP BY 1 ORDER BY 1 LIMIT %s'''          # parameterised; org_id from session
    with readonly_cursor(statement_timeout_ms=5000) as cur:
        cur.execute(sql, (org_id, args.start_date, args.end_date, args.limit))
        return [dict(r) for r in cur.fetchall()]

REGISTRY = {"get_sales_summary": (SalesSummaryArgs, get_sales_summary)}

def run_tool(name: str, raw_args: str, org_id: int) -> str:
    if name not in REGISTRY:
        return json.dumps({"error": f"unknown tool {name}"})
    model_cls, fn = REGISTRY[name]
    try:
        args = model_cls.model_validate_json(raw_args)
    except ValidationError as e:
        return json.dumps({"error": "invalid arguments", "details": e.errors(include_url=False)}, default=str)
    return json.dumps(fn(args, org_id=org_id), default=str)
