# The tool-call loop with an iteration cap
def answer(question: str, org_id: int, max_steps: int = 5) -> str:
    messages = [{"role": "system", "content": "Answer using tools. Never guess numbers."},
                {"role": "user", "content": question}]
    for _ in range(max_steps):
        resp = client.chat.completions.create(model=MODEL, messages=messages, tools=TOOLS)
        msg = resp.choices[0].message
        if not msg.tool_calls:
            return msg.content
        messages.append(msg.model_dump(exclude_none=True))   # assistant turn with tool_calls
        for call in msg.tool_calls:
            result = run_tool(call.function.name, call.function.arguments, org_id)
            messages.append({"role": "tool", "tool_call_id": call.id, "content": result})
    raise RuntimeError("tool loop exceeded max_steps")
